import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { publicAPI } from '../../services/api';
import Loader from '../../components/Loader';
import EmptyState from '../../components/EmptyState';
import Card from '../../components/Card';

const CampaignsPage = () => {
  const [campaigns, setCampaigns] = useState([]);
  const [loading,   setLoading]   = useState(true);
  const [error,     setError]     = useState('');

  useEffect(() => {
    publicAPI.getCampaigns()
      .then(res => setCampaigns(res.data))
      .catch(() => setError('Failed to load campaigns.'))
      .finally(() => setLoading(false));
  }, []);

  return (
    <div style={{ background: 'var(--eco-bg)', minHeight: '100vh' }}>
      <div className="section-header">
        <h1 className="section-header__title">🌍 Campaigns</h1>
        <p className="section-header__subtitle">Join clean-up drives and social sustainability initiatives.</p>
      </div>

      <div className="container" style={{ padding: 'var(--space-10) var(--space-6)' }}>
        {error   && <div className="alert alert-error">{error}</div>}

        {loading ? (
          <Loader text="Loading campaigns..." />
        ) : campaigns.length === 0 ? (
          <EmptyState icon="🌱" title="No campaigns yet" subtitle="New campaigns are added regularly. Check back soon!" />
        ) : (
          <div className="grid grid--auto">
            {campaigns.map(c => {
              const upcoming = new Date(c.date) > new Date();
              return (
                <div key={c.id} className="card" style={{ padding: 'var(--space-6)', borderTop: `4px solid ${upcoming ? 'var(--eco-primary)' : 'var(--eco-border)'}` }}>
                  <div className="flex-between mb-3">
                    <h3 style={{ fontFamily: 'var(--font-display)', fontSize: 'var(--text-md)', fontWeight: 700, lineHeight: 1.3 }}>
                      {c.title}
                    </h3>
                    <span className={`badge ${upcoming ? 'badge--success' : 'badge--neutral'}`} style={{ flexShrink: 0, marginLeft: 'var(--space-2)' }}>
                      {upcoming ? '🟢 Upcoming' : '⏸ Past'}
                    </span>
                  </div>
                  <p style={{ fontSize: 'var(--text-sm)', color: 'var(--eco-text-secondary)', lineHeight: 1.6, marginBottom: 'var(--space-4)' }}>{c.description}</p>
                  <div className="flex-col gap-1" style={{ fontSize: 'var(--text-sm)', color: 'var(--eco-text-muted)', marginBottom: upcoming ? 'var(--space-4)' : 0 }}>
                    <span>📍 {c.location}</span>
                    <span>📅 {new Date(c.date).toLocaleString('en-IN', { day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' })}</span>
                  </div>
                  {upcoming && (
                    <Link to="/register" className="btn btn--primary btn--sm btn--full" style={{ textAlign: 'center' }}>
                      Join Campaign →
                    </Link>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

export default CampaignsPage;
